package com.vibeguard.samples.imports; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Imports bounded CSV-style rows after administrator authentication. */ @RestController @RequestMapping("/internal/users/import") public class ImportController { @Value("${BULK_IMPORT_ADMIN_KEY:}") private String key; @PostMapping public ResponseEntity<Result> importUsers(@RequestHeader("X-Bulk-Import-Key") String supplied,@RequestBody String csv){if(!key.equals(supplied))return ResponseEntity.status(401).build();List<String> rows=Arrays.stream(csv.split("\\R")).filter(row->row.matches("[^,\\s]+,[^,]+") ).limit(1000).toList();return ResponseEntity.ok(new Result(rows.size()));}record Result(int importedCount){} }
